window.BT_EDITORIAL={"edition": "001", "preparedAt": "2026-11-02", "status": "published", "articles": [{"slug": "delta-reign-friday-uk-upc-release-check", "title": "Delta Reign arrives Friday. The UK UPC calendar needs a closer look.", "eyebrow": "THE RELEASE DESK", "summary": "Friday’s physical Delta launch is confirmed. The UK UPCs have a November window. Pictures and pack counts help you spot the right box.", "minutes": 4, "kind": "News", "date": "4 November 2026", "preparedAt": "2026-11-04", "publishedAt": "2026-11-04", "sourcePublishedAt": "2026-11-02", "status": "published", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "image": "assets/features-20261104/release-calendar-hero.png", "thumbnail": "assets/features-20261104/release-calendar-hero.png", "imageAlt": "Mega Rayquaza coils above a conceptual collector box and packs, with Espeon and Umbreon at either side, in red-and-ivory manga ink.", "imageCredit": "Illustration: BuyTrigger.Cards. Mega Rayquaza, Espeon and Umbreon with conceptual packaging.", "imageCaption": "Illustration: BuyTrigger.Cards. Mega Rayquaza, Espeon and Umbreon with conceptual packaging.", "visualStyle": "editorial-ink-v1", "sections": [{"heading": "At a glance", "html": "<aside class=\"quick-verdict\" aria-label=\"Quick takeaway\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Friday is Delta day. Check the UPC separately.</h3><p>Match the exact box, the UK date and your shop’s current notice before making the trip.</p></aside><p class=\"lede\">Delta Reign launches physically on Friday, 6 November. The UK anniversary UPCs have a November window; the official roundup gives no exact day. Here is how to spot each box before joining a queue.</p><p class=\"feature-source\"><a href=\"https://www.pokemon.com/uk/news/check-out-every-pokemon-tcg-product-release-in-november-2026\">Pokémon UK · November product roundup · 2 November 2026</a> · <a href=\"https://press.pokemon.com/en-NZ/MEDIA-ALERT-New-Pokemon-Trading-Card-Game-Mega-EvolutionDelta-Reign-Ex\">Pokémon · Delta Reign announcement · 20 August 2026</a></p><dl class=\"feature-facts\"><div><dt>Physical Delta launch</dt><dd>Friday, 6 November</dd></div><div><dt>TCG Live launch</dt><dd>Thursday, 5 November · 17:00 GMT</dd></div><div><dt>UK UPC / Ditto / figures</dt><dd>November window; exact day unstated</dd></div></dl>"}, {"heading": "A digital opening, then a physical release", "html": "<p>TCG Live is scheduled to receive the expansion at 17:00 GMT on Thursday, 5 November. The official forum notice lists the new packs, code redemption, Battle Pass and Build &amp; Battle event. These are digital milestones; a code becoming redeemable tells us nothing about a UK retailer’s shelf.</p><p>The physical set follows on Friday. Mega Rayquaza ex returns alongside three other Mega Evolution Pokémon ex. The expansion also introduces Legendary Stadiums made from two paired Stadium cards. Pokémon says a booster containing one includes both halves. Which illustrated cards turn up in a particular unopened box remains unknown.</p><p class=\"feature-source\"><a href=\"https://community.pokemon.com/en-us/discussion/26743/mega-evolution-delta-reign-expansion-release\">Official Pokémon Forums · digital launch · 30 October 2026</a> · <a href=\"https://press.pokemon.com/en-NZ/MEDIA-ALERT-New-Pokemon-Trading-Card-Game-Mega-EvolutionDelta-Reign-Ex\">Pokémon · Delta Reign announcement · 20 August 2026</a></p>"}, {"heading": "Two Elite Trainer Boxes, two configurations", "html": "<div class=\"product-reference-grid\"><figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/delta-etb.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Official Delta Reign regular Elite Trainer Box packaging.\"><img src=\"assets/features-20261104-visual-v3/delta-etb.webp\" alt=\"Official Delta Reign regular Elite Trainer Box packaging.\" loading=\"lazy\" decoding=\"async\"></a><figcaption><strong>Regular ETB: 9 packs.</strong> One full-art Kyogre promo. Official product reference © The Pokémon Company. <a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/delta-center-etb.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Official Delta Reign Pokémon Center Elite Trainer Box packaging.\"><img src=\"assets/features-20261104-visual-v3/delta-center-etb.webp\" alt=\"Official Delta Reign Pokémon Center Elite Trainer Box packaging.\" loading=\"lazy\" decoding=\"async\"></a><figcaption><strong>Pokémon Center ETB: 11 packs.</strong> Two Kyogre promos, one Center-stamped. Official product reference © The Pokémon Company. <a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure></div><p>The ordinary Elite Trainer Box contains nine packs and a full-art Kyogre promo. The Pokémon Center version contains eleven packs and two Kyogre promos, with the Center logo on one of them. The product name matters when comparing listings: an extra two packs and an extra stamped promo are a concrete configuration difference.</p><p>A Booster Bundle has six packs. A display contains 36. The Build &amp; Battle Box combines four packs with a ready-to-play 40-card deck containing one of four foil promos. Our chart compares pack quantities only. It leaves accessories, promos and price out of the ranking.</p><p class=\"feature-source\"><a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\">Pokémon UK · Delta Reign product showcase · 23 October 2026</a></p><figure class=\"feature-chart\" id=\"delta-pack-counts\"><h3>Announced Delta Reign pack counts</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/features-20261104/delta-pack-counts-mobile.png\"/><img alt=\"Announced Delta Reign pack counts. Booster display, 36; Pokémon Center ETB, 11; Regular ETB, 9; Booster Bundle, 6; Build &amp; Battle, 4. Manufacturer configurations; quantities do not establish price, pull odds or value.\" loading=\"lazy\" src=\"assets/features-20261104/delta-pack-counts.png\"/></picture><figcaption>Manufacturer configurations; quantities do not establish price, pull odds or value.</figcaption><p class=\"source\"><a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\">Pokémon UK · Delta Reign product showcase · 23 October 2026</a></p><details><summary>View data and downloads</summary><div class=\"table-scroll\"><table><thead><tr><th>Product</th><th>Packs</th></tr></thead><tbody><tr><td>Booster display</td><td>36</td></tr><tr><td>Pokémon Center ETB</td><td>11</td></tr><tr><td>Regular ETB</td><td>9</td></tr><tr><td>Booster Bundle</td><td>6</td></tr><tr><td>Build &amp; Battle</td><td>4</td></tr></tbody></table></div><p><a download=\"\" href=\"assets/features-20261104/delta-pack-counts.csv\">CSV data</a> · <a download=\"\" href=\"assets/features-20261104/delta-pack-counts.svg\">Editable SVG</a> · <a download=\"\" href=\"assets/features-20261104/delta-pack-counts.pdf\">Chart PDF</a></p></details></figure>"}, {"heading": "The UPC’s 29-plus-1 deserves its own label", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/upc-day-night.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Official 30th Celebration Day and Night Ultra-Premium Collection boxes shown together.\"><img src=\"assets/features-20261104-visual-v3/upc-day-night.webp\" alt=\"Official 30th Celebration Day and Night Ultra-Premium Collection boxes shown together.\" loading=\"lazy\" decoding=\"async\"></a><figcaption><strong>Day = Espeon. Night = Umbreon.</strong> Both pair their featured Pokémon with Pikachu ex. Official packaging reference © The Pokémon Company; UK availability is a November window, not confirmed stock. <a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-30th-celebration-product-showcase\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><p>Each English Day or Night Ultra-Premium Collection has 29 regular 30th Celebration boosters and one separate Classic Collection pack containing three cards. Calling that simply 30 packs loses a useful distinction: the last pack is a different product component.</p><p>Day pairs Pikachu ex with Espeon ex; Night pairs Pikachu ex with Umbreon ex. Both also include themed accessories. The chart below preserves the two pack types. Keep the Classic pack separate when comparing boxes.</p><p class=\"feature-source\"><a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-30th-celebration-product-showcase\">Pokémon UK · 30th Celebration product showcase · 30 June 2026</a></p><figure class=\"feature-chart\" id=\"upc-pack-mix\"><h3>The UPC contains two pack types</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/features-20261104/upc-pack-mix-mobile.png\"/><img alt=\"The UPC contains two pack types. Regular 30th boosters, 29; Classic Collection pack, 1. English Day/Night configuration: 29 regular boosters plus one three-card Classic Collection pack.\" loading=\"lazy\" src=\"assets/features-20261104/upc-pack-mix.png\"/></picture><figcaption>English Day/Night configuration: 29 regular boosters plus one three-card Classic Collection pack.</figcaption><p class=\"source\"><a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-30th-celebration-product-showcase\">Pokémon UK · 30th Celebration product showcase · 30 June 2026</a></p><details><summary>View data and downloads</summary><div class=\"table-scroll\"><table><thead><tr><th>Pack type</th><th>Quantity</th></tr></thead><tbody><tr><td>Regular 30th boosters</td><td>29</td></tr><tr><td>Classic Collection pack</td><td>1</td></tr></tbody></table></div><p><a download=\"\" href=\"assets/features-20261104/upc-pack-mix.csv\">CSV data</a> · <a download=\"\" href=\"assets/features-20261104/upc-pack-mix.svg\">Editable SVG</a> · <a download=\"\" href=\"assets/features-20261104/upc-pack-mix.pdf\">Chart PDF</a></p></details></figure>"}, {"heading": "Read the UK date as it is written", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/release-queue-alex-oscar.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Conceptual manga illustration of Alex checking a phone while Oscar and Pikachu wait outside a fictional card shop.\"><img src=\"assets/features-20261104-visual-v3/release-queue-alex-oscar.webp\" alt=\"Conceptual manga illustration of Alex checking a phone while Oscar and Pikachu wait outside a fictional card shop.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Illustration: BuyTrigger.Cards. Alex, Oscar and Pikachu in a fictional release-day scene.</figcaption></figure><p>The 2 November UK roundup gives the UPC, Ditto and Mew/Mewtwo figure collections month-only availability. That supports a November release window. A UK launch day or revised schedule needs a separate dated confirmation.</p><p>For an actual shop visit, narrow the question to the exact edition, retailer and branch. Check whether its date describes release, dispatch or collection. A product listing and a paid preorder confirmation answer different questions from a current stock notice.</p><p class=\"feature-source\"><a href=\"https://www.pokemon.com/uk/news/check-out-every-pokemon-tcg-product-release-in-november-2026\">Pokémon UK · November product roundup · 2 November 2026</a></p>"}, {"heading": "The verdict before you queue", "html": "<div class=\"closing-call\"><p><strong>Put physical Delta Reign on Friday’s calendar.</strong> Keep the UK UPC date open until your exact retailer confirms it.</p><ul><li>Check the branch’s current stock, opening time and purchase limits.</li><li>Choose the right box: regular ETB 9 packs; Center ETB 11.</li><li>For the UPC, compare 29 regular boosters plus one three-card Classic pack.</li></ul><p>A release date gives you a plan. A current shop notice tells you whether the trip makes sense.</p></div><figure class=\"source-shot\"><img alt=\"Screenshot excerpt of the official Pokémon press announcement headline for Delta Reign.\" loading=\"lazy\" src=\"assets/features-20261104/delta-announcement-heading.png\"/><figcaption>Source excerpt: The Pokémon Company International, announcement dated 20 August 2026. Captured 4 November; headline only. <a href=\"https://press.pokemon.com/en-NZ/MEDIA-ALERT-New-Pokemon-Trading-Card-Game-Mega-EvolutionDelta-Reign-Ex\">Open the original source ↗</a></figcaption></figure>"}], "sources": [{"label": "Pokémon UK · November product roundup · 2 November 2026", "url": "https://www.pokemon.com/uk/news/check-out-every-pokemon-tcg-product-release-in-november-2026"}, {"label": "Pokémon · Delta Reign announcement · 20 August 2026", "url": "https://press.pokemon.com/en-NZ/MEDIA-ALERT-New-Pokemon-Trading-Card-Game-Mega-EvolutionDelta-Reign-Ex"}, {"label": "Official Pokémon Forums · digital launch · 30 October 2026", "url": "https://community.pokemon.com/en-us/discussion/26743/mega-evolution-delta-reign-expansion-release"}, {"label": "Pokémon UK · Delta Reign product showcase · 23 October 2026", "url": "https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase"}, {"label": "Pokémon UK · 30th Celebration product showcase · 30 June 2026", "url": "https://www.pokemon.com/uk/news/pokemon-tcg-30th-celebration-product-showcase"}], "related": ["delta-reign-product-guide-october", "psa-backlog-november-2026-collector-guide", "how-the-index-works"], "cta": {"href": "#drops", "label": "Check the release calendar"}, "eventDate": "2026-11-06", "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1"}, {"slug": "psa-backlog-november-2026-collector-guide", "title": "PSA’s backlog is shrinking. What does 6.8 million mean for collectors?", "eyebrow": "THE GRADING DESK", "summary": "PSA’s reported queue is about 31% smaller than in early September. There are still 6.8 million units waiting, and your order keeps its original terms.", "minutes": 4, "kind": "News", "date": "4 November 2026", "preparedAt": "2026-11-04", "publishedAt": "2026-11-04", "sourcePublishedAt": "2026-11-03", "status": "published", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "image": "assets/features-20261104-visual-v3/psa-pikachu-queue.webp", "thumbnail": "assets/features-20261104-visual-v3/psa-pikachu-queue.webp", "imageAlt": "Pikachu peers over a parcel in a winding submission queue beside an oversized clock and blank card holder, in red-and-ivory manga ink.", "imageCredit": "Illustration: BuyTrigger.Cards. Pikachu in a conceptual grading queue.", "imageCaption": "Illustration: BuyTrigger.Cards. Pikachu in a conceptual grading queue.", "visualStyle": "editorial-ink-v1", "sections": [{"heading": "At a glance", "html": "<aside class=\"quick-verdict\" aria-label=\"Quick takeaway\"><span class=\"kicker\">THE QUICK TAKE</span><h3>The queue is improving. Your order keeps its own terms.</h3><p>PSA’s reported backlog is about 31% smaller than on 8 September. There are still 6.8 million units waiting, and no Value Bulk reopening date.</p></aside><p class=\"lede\">PSA reports an active grading backlog of 6.8 million units in its 3 November update, down from 7.2 million on 20 October. For an individual order, the service and its original terms still matter.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/info/backlog-tracker\">PSA · reported active backlog · latest entry 3 November 2026</a></p><dl class=\"feature-facts\"><div><dt>Latest reported backlog</dt><dd>6.8 million units · 3 November</dd></div><div><dt>Latest net reduction</dt><dd>0.4 million units · 20 October–3 November</dd></div><div><dt>Value Bulk reopening</dt><dd>No date announced in this update</dd></div></dl>"}, {"heading": "The queue since September", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Three PSA-encapsulated trading cards in the official 28 October Value-service announcement photograph.\"><img src=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" alt=\"Three PSA-encapsulated trading cards in the official 28 October Value-service announcement photograph.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>PSA’s 28 October announcement photograph © PSA/Collectors. These are the publisher’s example cards; they do not predict a reader’s grade or return date. <a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><p>The chart uses five dated observations from PSA’s tracker. It falls from 9.9 million on 8 September to 6.8 million on 3 November. The latest interval is smaller than the preceding one. PSA attributes that slower reduction to additional submissions after Value reopened, while saying daily output stayed consistent with recent production.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/info/backlog-tracker\">PSA · reported active backlog · latest entry 3 November 2026</a></p><figure class=\"feature-chart\" id=\"psa-backlog\"><h3>PSA’s reported active grading backlog</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/features-20261104/psa-backlog-mobile.png\"/><img alt=\"PSA’s reported active grading backlog. 2026-09-08, 9.9; 2026-09-22, 9; 2026-10-06, 8.2; 2026-10-20, 7.2; 2026-11-03, 6.8. Five reported observations, 8 September–3 November 2026. These are remaining units, not units graded.\" loading=\"lazy\" src=\"assets/features-20261104/psa-backlog.png\"/></picture><figcaption>Five reported observations, 8 September–3 November 2026. These are remaining units, not units graded.</figcaption><p class=\"source\"><a href=\"https://www.psacard.com/info/backlog-tracker\">PSA · reported active backlog · latest entry 3 November 2026</a></p><details><summary>View data and downloads</summary><div class=\"table-scroll\"><table><thead><tr><th>Report date</th><th>Million units</th></tr></thead><tbody><tr><td>2026-09-08</td><td>9.9</td></tr><tr><td>2026-09-22</td><td>9</td></tr><tr><td>2026-10-06</td><td>8.2</td></tr><tr><td>2026-10-20</td><td>7.2</td></tr><tr><td>2026-11-03</td><td>6.8</td></tr></tbody></table></div><p><a download=\"\" href=\"assets/features-20261104/psa-backlog.csv\">CSV data</a> · <a download=\"\" href=\"assets/features-20261104/psa-backlog.svg\">Editable SVG</a> · <a download=\"\" href=\"assets/features-20261104/psa-backlog.pdf\">Chart PDF</a></p></details></figure>"}, {"heading": "A falling backlog is a net change", "html": "<figure class=\"queue-explainer\"><h3>Why a smaller queue is only part of the picture</h3><div class=\"visual-steps\"><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 22h36v29H14zM14 22l18-10 18 10M32 12v17M22 38h20M32 30v16\"/></svg><strong>New submissions enter</strong><p>Incoming work adds to the queue.</p></div><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 26h13v26H10zM26 19h13v33H26zM42 12h13v40H42zM8 57h49\"/></svg><strong>The backlog is what remains</strong><p>6.8 million active units on 3 November.</p></div><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"15\" y=\"7\" width=\"34\" height=\"49\" rx=\"3\"/><path d=\"M20 17h24M23 36l7 7 13-16\"/></svg><strong>Completed work leaves</strong><p>Output reduces the queue as work finishes.</p></div></div><figcaption>Concept diagram: the net queue change combines arrivals and completed work. The tracker does not give the period’s total throughput.</figcaption></figure><p>Backlog measures work still waiting. It changes when new work enters and when work leaves. A reduction of 400,000 units therefore cannot, by itself, tell us how many cards PSA graded during that period.</p><p>That is why this chart has no projected zero-backlog date. Extending the last line segment would assume that arrivals and output keep behaving in the same way. The tracker supplies a history of reported queue sizes, not the inputs for that forecast.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/info/backlog-tracker\">PSA · reported active backlog · latest entry 3 November 2026</a></p>"}, {"heading": "The service estimates answer a different question", "html": "<p>PSA’s 28 October announcement gave estimated business-day ranges of 90–100 for Value outside Japan, 70–80 for Standard and 50–60 for Priority. The chart reproduces those announced ranges. Use the ranges to compare announced services alongside their fees and eligibility.</p><p>The same announcement priced direct US Value at US$39.99 with a US$500 maximum insured value, and listed €39.99 for Europe. Japan’s Value estimate was 120 business days. These are region-specific service terms; a UK intermediary’s all-in quote must be checked separately.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\">PSA · service changes announced 28 October 2026</a></p><figure class=\"feature-chart\" id=\"psa-turnaround\"><h3>Announced turnaround ranges</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/features-20261104/psa-turnaround-mobile.png\"/><img alt=\"Announced turnaround ranges. Value, 90, 100; Standard, 70, 80; Priority, 50, 60. 28 October announcement; business-day estimates outside Japan. Japan Value: 120 business days. Existing orders keep their original terms.\" loading=\"lazy\" src=\"assets/features-20261104/psa-turnaround.png\"/></picture><figcaption>28 October announcement; business-day estimates outside Japan. Japan Value: 120 business days. Existing orders keep their original terms.</figcaption><p class=\"source\"><a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\">PSA · service changes announced 28 October 2026</a></p><details><summary>View data and downloads</summary><div class=\"table-scroll\"><table><thead><tr><th>Service</th><th>Low estimate</th><th>High estimate</th></tr></thead><tbody><tr><td>Value</td><td>90</td><td>100</td></tr><tr><td>Standard</td><td>70</td><td>80</td></tr><tr><td>Priority</td><td>50</td><td>60</td></tr></tbody></table></div><p><a download=\"\" href=\"assets/features-20261104/psa-turnaround.csv\">CSV data</a> · <a download=\"\" href=\"assets/features-20261104/psa-turnaround.svg\">Editable SVG</a> · <a download=\"\" href=\"assets/features-20261104/psa-turnaround.pdf\">Chart PDF</a></p></details></figure>"}, {"heading": "An older order keeps its original terms", "html": "<div class=\"visual-steps order-checks\"><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 8h34v48l-6-5-6 5-5-5-5 5-6-5-6 5zM23 20h18M23 29h18M23 38h11\"/></svg><strong>Keep the confirmation</strong><p>Use the date and terms on your original order.</p></div><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"11\" y=\"14\" width=\"42\" height=\"37\" rx=\"3\"/><path d=\"M11 24h42M20 34h24M20 42h15\"/></svg><strong>Check the service level</strong><p>New estimates do not rewrite an older order.</p></div><div><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 17h33v29H6zM39 26h11l9 12v8H39z\"/><circle cx=\"18\" cy=\"49\" r=\"6\"/><circle cx=\"49\" cy=\"49\" r=\"6\"/></svg><strong>Count the whole route</strong><p>Include transport, handling and any taxes in a UK quote.</p></div></div><p>PSA said the revised Standard and Priority estimates apply to orders submitted from 28 October at 8am Pacific. Existing orders retain the terms under which they entered, even if processing becomes faster. Its November update also reiterates that existing orders keep priority ahead of new Value submissions.</p><p>Keep the original confirmation, service level and current status together. That is the record to check against any new service announcement.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\">PSA · service changes announced 28 October 2026</a> · <a href=\"https://www.psacard.com/info/backlog-tracker\">PSA · reported active backlog · latest entry 3 November 2026</a></p>"}, {"heading": "Read business days and route costs carefully", "html": "<p>PSA’s service page describes turnaround times as estimates that can change with submission volume and capacity. Before counting forward, confirm the timing terms that apply to the actual order. Business days, transport and a submitter’s handling stages belong to different parts of the journey.</p><p>For a UK route, compare the quoted grading charge with insured shipping, return delivery and any handling or tax charges. A direct US fee supplies one part of that calculation. Paying for a faster service also leaves the card’s eventual grade unresolved: authentication and condition assessment still have to happen.</p><p class=\"feature-source\"><a href=\"https://www.psacard.com/services/tradingcardgrading\">PSA · US grading services and estimate terms · checked 4 November 2026</a></p>"}, {"heading": "The verdict for your submission", "html": "<div class=\"closing-call\"><p><strong>The direction is encouraging: PSA’s reported queue fell from 9.9 million to 6.8 million units.</strong> That is roughly 31% smaller since 8 September.</p><p>For an existing submission, keep the original service terms and status as your reference. For a new UK route, compare the full delivered cost and applicable business-day estimate. Value Bulk still has no announced reopening date in the latest update.</p><p class=\"feature-source\">Our calculation: (9.9 − 6.8) ÷ 9.9 = 31.3%, rounded to 31%. Source: PSA’s dated backlog readings. Next check: a new backlog update or an actual Bulk reopening announcement.</p></div><figure class=\"source-shot\"><img alt=\"Screenshot excerpt showing the PSA Backlog Tracker heading and its update-frequency strapline.\" loading=\"lazy\" src=\"assets/features-20261104/psa-report-heading.png\"/><figcaption>Source excerpt: PSA Backlog Tracker, captured 4 November 2026. The latest dated entry used in this article is 3 November. <a href=\"https://www.psacard.com/info/backlog-tracker\">Open the original source ↗</a></figcaption></figure>"}], "sources": [{"label": "PSA · reported active backlog · latest entry 3 November 2026", "url": "https://www.psacard.com/info/backlog-tracker"}, {"label": "PSA · service changes announced 28 October 2026", "url": "https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level"}, {"label": "PSA · US grading services and estimate terms · checked 4 November 2026", "url": "https://www.psacard.com/services/tradingcardgrading"}], "related": ["psa-value-returns", "psa10-is-not-profit", "delta-reign-friday-uk-upc-release-check"], "cta": {"href": "#calculator", "label": "Try the grading maths"}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1"}, {"slug": "japanese-card-research", "title": "Same artwork. A different market.", "eyebrow": "JAPAN DESK", "summary": "Same artwork can lead to different prices. Start with the language and exact printing, then check supply, condition and the market where you would sell.", "minutes": 4, "art": "japan", "date": "2 November 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Match the issue before comparing the price.</h3><p>Language, set, collector number and grade belong in the comparison. Shared artwork is the beginning of the research.</p></aside>"}, {"heading": "The picture is familiar. The issue still matters.", "html": "<figure class=\"feature-reference\"><a href=\"assets/modern-006-high.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\"><img src=\"assets/modern-006-high.webp\" alt=\"English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>English Umbreon VMAX · Evolving Skies · 215/203. Catalogue artwork via TCGdex; © Pokémon/Nintendo/Creatures/GAME FREAK. A reference scan does not establish a seller copy’s condition. <a href=\"https://api.tcgdex.net/v2/en/sets/swsh7\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure>"}, {"heading": "Check the identity first", "html": "<p>A Japanese card and an English card can share artwork while trading in different markets. Record the language, set, collector number, finish and grade before comparing prices. The English Umbreon reference above shows what an exact identity looks like; it is not a Japanese price comparison.</p><p>A reference scan helps identify a printing. It does not show the condition of a particular copy offered for sale. Ask for original front and back photographs before judging centring, corners, edges or surface.</p>"}, {"heading": "Supply has more than one language", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Same artwork</strong><p>Check which other-language releases carry it.</p></div><div><b>2</b><strong>Actual availability</strong><p>Look at current listings and completed sales in the relevant market.</p></div><div><b>3</b><strong>Graded population</strong><p>PSA counts graded examples; raw cards and unopened product remain outside that count.</p></div></div><p>Review where the artwork appears across English, Japanese and other-language releases. Check observed availability and announced products, and keep those two things separate. Difficult pulls from one English set do not, on their own, establish worldwide artwork scarcity.</p><p>A population report answers a narrower question: how many examples a grader has recorded at each grade. It does not count every raw copy still in binders, shops or unopened product.</p>"}, {"heading": "Bring the price back to your market", "html": "<p>For an overseas listing, record the source currency and the full delivered entry, including the applicable shipping, handling, tax and currency-conversion costs. An attractive yen headline can change considerably by arrival.</p><p>Then examine recent exact Japanese-card sales where you expect to sell. A few exceptional transactions are different evidence from a regular flow of buyers. Thin sales and stale guides should remain visible.</p><div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Check</th><th>Keep with the comparison</th></tr></thead><tbody><tr><td>Entry</td><td>Available copy + delivered cost + source currency</td></tr><tr><td>Exit</td><td>Exact issue and grade + recent completed sales</td></tr><tr><td>Evidence</td><td>Sale date, original URL and any uncertainty</td></tr></tbody></table></div>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>A lower foreign-language price is a lead, not a finished valuation.</strong> Match the exact issue, investigate global same-art supply and check attainable local exits. When evidence is thin, keep researching rather than filling the gap with a confident buy label.</p></div>"}], "sources": [{"label": "PSA · definition of graded population", "url": "https://www.psacard.com/psasetregistry/glossary"}, {"label": "TCGdex · English Evolving Skies catalogue", "url": "https://api.tcgdex.net/v2/en/sets/swsh7"}], "related": ["under20-upside", "how-the-index-works"], "cta": {"label": "Open the Japan research desk", "href": "#japan"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "sourcePublishedAt": "2026-11-01", "kind": "Japan", "publishedAt": "2026-11-03", "status": "published", "image": "assets/archive-refresh-20261104/cover-japan.webp", "visualStyle": "brand-graphic-v1", "imageAlt": "English Umbreon VMAX catalogue artwork beside the words One art. Two markets.", "imageCredit": "BuyTrigger.Cards editorial graphic using an English catalogue reference via TCGdex. No price comparison is implied.", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-japan.webp", "imageCaption": "BuyTrigger.Cards editorial graphic using an English catalogue reference via TCGdex. No price comparison is implied.", "retrospective": true}, {"slug": "psa-value-returns", "title": "PSA Value is back. What changes for collectors?", "eyebrow": "THE GRADING DESK", "summary": "The October reopening brought a US$39.99 direct service and revised estimates. Here is what applies to a new submission—and what an existing order keeps.", "minutes": 4, "art": "news", "date": "2 November 2026", "sourceDate": "PSA announcement · 28 October 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Value reopened behind existing orders.</h3><p>PSA’s 28 October announcement set a lower-priced service and new estimates. An older order keeps the terms under which it entered.</p></aside>"}, {"heading": "The announcement, in order", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\"><img src=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" alt=\"Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>PSA announcement photograph © PSA/Collectors, 28 October 2026. The pictured cards are source examples; calculations in our guides are hypothetical. <a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><ol class=\"archive-timeline\"><li><b>28 Oct 2026</b><span>PSA announces the service changes. New Standard/Priority estimates apply from 8am Pacific.</span></li><li><b>29 Oct 2026</b><span>Value reopening announced for 8am Pacific.</span></li><li><b>3 Nov 2026</b><span>Our original publication of this retrospective.</span></li><li><b>4 Nov 2026</b><span>This visual guide is updated; the original publication date is retained.</span></li></ol>"}, {"heading": "What the dated service terms say", "html": "<div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Service</th><th>Announced estimate outside Japan</th></tr></thead><tbody><tr><td>Value</td><td>90–100 business days</td></tr><tr><td>Standard</td><td>70–80 business days</td></tr><tr><td>Priority</td><td>50–60 business days</td></tr></tbody></table></div><p>The announcement priced direct US Value at US$39.99, with a US$500 maximum insured value. It gave a 90–100-business-day estimate outside Japan; Japan was listed at 120. Standard and Priority were listed at 70–80 and 50–60 business days respectively.</p><p>Those are the terms announced then, rather than a fresh all-in UK intermediary quote. New Value orders were to follow work already in the queue.</p>"}, {"heading": "Check the whole route", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Original order</strong><p>Retain your confirmation, date and service level.</p></div><div><b>2</b><strong>Full cost</strong><p>Add insured transport, handling, return delivery and applicable taxes.</p></div><div><b>3</b><strong>Grade outcomes</strong><p>Compare the net result at Raw, PSA 9 and PSA 10; an attractive top grade is not assured.</p></div></div><figure class=\"feature-reference\"><a href=\"assets/editorial-grading-desk-v1.jpg\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Illustration of a card being inspected with a magnifying glass.\"><img src=\"assets/editorial-grading-desk-v1.jpg\" alt=\"Illustration of a card being inspected with a magnifying glass.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Illustration: BuyTrigger.Cards. Conceptual card inspection.</figcaption></figure>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>Use the reopening announcement to understand the service choice, then check the terms for your own route and order.</strong> The headline grading fee is one cost. For the newer queue reading, open our 3 November backlog analysis.</p></div>"}], "sources": [{"label": "PSA · original 28 October service announcement", "url": "https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level"}, {"label": "PSA · latest dated backlog updates", "url": "https://www.psacard.com/info/backlog-tracker"}], "related": ["psa10-is-not-profit", "under20-upside"], "cta": {"label": "Try the grading-cost calculator", "href": "#calculator"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "sourcePublishedAt": "2026-10-28", "eventDate": "2026-10-28", "kind": "News", "publishedAt": "2026-11-03", "status": "published", "image": "assets/features-20261104-visual-v3/psa-value-announcement.webp", "imageAlt": "Three encapsulated trading cards in PSA’s Value-service announcement photograph.", "imageCaption": "PSA announcement photograph © PSA/Collectors, 28 October 2026. Source linked below.", "imageCredit": "PSA announcement photograph © PSA/Collectors, 28 October 2026. Source linked below.", "visualStyle": "source-media-v1", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/features-20261104-visual-v3/psa-value-announcement.webp", "retrospective": true}, {"slug": "psa-october-theft-update", "title": "PSA publishes stolen-card list after October shipment theft", "eyebrow": "Archive · Grading & collector safety", "summary": "The October statement published item identities and explained different customer routes. A visual guide to the dates, records and checks that matter.", "minutes": 4, "art": "archive", "date": "2026-11-02", "eventDate": "2026-10-13", "sourcePublishedAt": "2026-10-23", "preparedAt": "2026-11-02", "dateNote": "Incident: 13 October. PSA statement: 23 October. Retrospective prepared 2 November; no later recovery status verified.", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Check the official list. Keep your records together.</h3><p>PSA’s 23 October statement identified 6,451 stolen items and said affected graded certificates had been deactivated. This is a guide to that statement, not a new recovery report.</p></aside>"}, {"heading": "The dates behind the headline", "html": "<ol class=\"archive-timeline\"><li><b>13 Oct 2026</b><span>The theft occurred after carrier pickup from PSA’s Santa Ana facility, according to PSA.</span></li><li><b>23 Oct 2026</b><span>PSA publishes its statement and item list.</span></li><li><b>3 Nov 2026</b><span>Our original retrospective is published.</span></li><li><b>4 Nov 2026</b><span>Visual guide updated; check the official source for later developments.</span></li></ol><figure class=\"feature-reference\"><a href=\"assets/editorial-grading-desk-v1.jpg\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Illustration of a card being inspected with a magnifying glass.\"><img src=\"assets/editorial-grading-desk-v1.jpg\" alt=\"Illustration of a card being inspected with a magnifying glass.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Illustration: BuyTrigger.Cards. Conceptual card inspection.</figcaption></figure>"}, {"heading": "What the company said", "html": "<p>PSA reported multiple customer orders stolen from a FedEx truck after collection from its Santa Ana facility. It said local and federal investigators were involved, and published an item-level list with certification and serial numbers where available.</p><p>Its statement said affected graded certificates were deactivated and the list shared with marketplaces and auction houses. Grading-fee refunds were described separately from compensation for the items. The stated arrangements depended on whether the customer used PSA’s label, their own label or a dealer.</p>"}, {"heading": "Make an identity check useful", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Keep a clear label photo</strong><p>Connect the certificate to the physical card and original order.</p></div><div><b>2</b><strong>Use the original list</strong><p>Follow PSA’s statement to its published list and support instructions.</p></div><div><b>3</b><strong>Verify a concerning match</strong><p>Use the relevant official channel; a screenshot alone is not a reason to accuse a seller.</p></div></div><div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Record</th><th>Why it helps</th></tr></thead><tbody><tr><td>Slab front and label</td><td>Preserves the item identity</td></tr><tr><td>Receipt and order details</td><td>Connects the card to its acquisition/submission</td></tr><tr><td>Shipping and cover terms</td><td>Shows the route and applicable arrangements</td></tr></tbody></table></div>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>Identity records and original-source checks are the useful next steps.</strong> Start with PSA’s statement and linked list. A refund of grading fees and compensation for the item are separate matters; use the company’s actual instructions for the affected route.</p></div>"}], "sources": [{"label": "PSA — Stolen PSA Orders: What We’re Doing and How You Can Help · 23 October 2026", "url": "https://www.psacard.com/articles/articleview/15778/psa-theft-update", "publishedAt": "2026-10-23", "checkedAt": "2026-11-02", "type": "Original company statement"}], "related": ["psa-value-returns", "psa10-is-not-profit"], "cta": {"label": "Read the original PSA statement and item list", "href": "https://www.psacard.com/articles/articleview/15778/psa-theft-update"}, "bodyWordCount": 285, "reportedWordCount": 137, "kind": "News", "publicationStatus": "Published 3 November 2026", "image": "assets/archive-refresh-20261104/cover-safety.webp", "imageAlt": "A large locked parcel beside the words Check the cert. Keep the records together.", "imageCredit": "Illustration: BuyTrigger.Cards. Conceptual parcel and security check; not an image of the incident.", "publishedAt": "2026-11-03", "status": "published", "visualStyle": "brand-graphic-v1", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-safety.webp", "imageCaption": "Illustration: BuyTrigger.Cards. Conceptual parcel and security check; not an image of the incident.", "retrospective": true}, {"slug": "delta-reign-product-guide-october", "title": "Delta Reign: what the October product showcase actually tells us", "eyebrow": "Archive · Physical TCG releases", "summary": "The ordinary ETB, Pokémon Center ETB, bundle, display and Build & Battle serve different collecting jobs. The pictures and pack counts explain the difference.", "minutes": 4, "art": "archive", "date": "2026-11-02", "eventDate": "2026-10-23", "sourcePublishedAt": "2026-10-23", "preparedAt": "2026-11-02", "announcedReleaseDate": "2026-11-06", "dateNote": "Announcement published 23 October; release was announced for 6 November. Current retail stock and prices were not checked.", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Identify the box before comparing the price.</h3><p>The 23 October showcase described five configurations. They carry different pack counts and extras, so a cheaper headline does not settle the comparison.</p></aside>"}, {"heading": "Two boxes that are easy to confuse", "html": "<div class=\"product-reference-grid\"><figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/delta-etb.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Regular Delta Reign Elite Trainer Box packaging.\"><img src=\"assets/features-20261104-visual-v3/delta-etb.webp\" alt=\"Regular Delta Reign Elite Trainer Box packaging.\" loading=\"lazy\" decoding=\"async\"></a><figcaption><strong>Regular ETB · 9 packs</strong> and one full-art Kyogre promo. © The Pokémon Company. <a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/delta-center-etb.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Pokémon Center Delta Reign Elite Trainer Box packaging.\"><img src=\"assets/features-20261104-visual-v3/delta-center-etb.webp\" alt=\"Pokémon Center Delta Reign Elite Trainer Box packaging.\" loading=\"lazy\" decoding=\"async\"></a><figcaption><strong>Center ETB · 11 packs</strong> and two Kyogre promos, one Center-stamped. © The Pokémon Company. <a href=\"https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure></div><div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Format</th><th>Delta Reign packs</th><th>Useful distinction</th></tr></thead><tbody><tr><td>Booster display</td><td>36</td><td>Packs-focused configuration</td></tr><tr><td>Pokémon Center ETB</td><td>11</td><td>Two Kyogre promos, one Center-stamped</td></tr><tr><td>Regular ETB</td><td>9</td><td>One Kyogre promo</td></tr><tr><td>Booster Bundle</td><td>6</td><td>Smaller packs-focused format</td></tr><tr><td>Build & Battle</td><td>4</td><td>40-card deck and one of four foil promos</td></tr></tbody></table></div>"}, {"heading": "What the announcement establishes", "html": "<p>Pokémon’s UK showcase dated the physical expansion for 6 November and described more than 135 cards. The table reproduces its announced pack quantities; promos, accessories and decks remain separate parts of the configuration.</p><p>A count of packs is useful for identifying a listing. It does not establish the box’s retail price, local stock, pull odds, print run or expected resale outcome. Check a current retailer notice separately before travelling.</p>"}, {"heading": "Choose the collecting job", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Opening packs</strong><p>Compare pack quantity with the complete delivered price.</p></div><div><b>2</b><strong>Chasing the included promo</strong><p>Match the exact edition and any stamp; do not treat both ETBs as interchangeable.</p></div><div><b>3</b><strong>Starting a game</strong><p>Look at the included deck and play accessories, not just the pack count.</p></div></div><p>A useful product comparison starts with the exact box and edition. Write those down before looking at a seller’s headline price. Otherwise, a cheaper-looking listing can appear to beat a product that includes different contents.</p><p>Then separate your reason for wanting it. Someone interested in an included promo is answering a different question from someone who wants packs for a family opening session or a ready-made starting point for play. A single “best value” label can hide those differences.</p><p>For a watchlist, we would keep a product’s announcement date, intended release date, edition and contents together. A later retailer check should add its own date and delivered price rather than silently replacing the original announcement. That makes it possible to see what was promised and what subsequently appeared.</p><p>The same discipline belongs in the TCG Modern Index: identify the exact collectible before measuring anything. A release headline can explain the calendar; it cannot supply missing transaction data or prove that a card has become undervalued.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>There is no single best box without a purpose and a real price.</strong> Match the exact configuration first, then check availability and your reason for choosing it. Our newer Friday/UPC Feature adds the UK calendar distinctions.</p></div>"}], "sources": [{"label": "Pokémon UK — Delta Reign product showcase · 23 October 2026", "url": "https://www.pokemon.com/uk/news/pokemon-tcg-mega-evolution-delta-reign-product-showcase", "publishedAt": "2026-10-23", "checkedAt": "2026-11-02", "type": "Original product announcement"}], "related": ["how-the-index-works", "japanese-card-research"], "cta": {"label": "Read the latest Friday and UK UPC check", "href": "#read/delta-reign-friday-uk-upc-release-check"}, "bodyWordCount": 299, "reportedWordCount": 134, "kind": "News", "publicationStatus": "Published 3 November 2026", "image": "assets/features-20261104-visual-v3/delta-center-etb.webp", "imageAlt": "Official Delta Reign Pokémon Center Elite Trainer Box packaging.", "imageCredit": "Official Delta Reign Pokémon Center Elite Trainer Box reference © The Pokémon Company. Source: 23 October UK product showcase.", "publishedAt": "2026-11-03", "status": "published", "visualStyle": "source-media-v1", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/features-20261104-visual-v3/delta-center-etb.webp", "imageCaption": "Official Delta Reign Pokémon Center Elite Trainer Box reference © The Pokémon Company. Source: 23 October UK product showcase.", "retrospective": true}, {"slug": "pokemon-santa-cruz-card-art", "title": "From binder to board: Pokémon card art meets Santa Cruz", "eyebrow": "Archive · Art & collecting culture", "summary": "Charizard, Lugia and Umbreon move from small cards to full-sized decks. The official pictures show what changes when the artwork gets more room.", "minutes": 4, "art": "archive", "date": "2026-11-02", "eventDate": "2026-10-17", "sourcePublishedAt": "2026-10-17", "preparedAt": "2026-11-02", "dateNote": "Reports the official 17 October launch announcement. Availability and resale prices were not rechecked on 2 November.", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Look at the artwork at a completely different scale.</h3><p>Pokémon’s 17 October collaboration put TCG illustrations onto Santa Cruz decks. This is an art story; the announcement is not a current stock or resale-price check.</p></aside>"}, {"heading": "From a card to a deck", "html": "<figure class=\"feature-reference\"><a href=\"assets/archive-refresh-20261104/santa-cruz-details.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Official Santa Cruz decks featuring Venusaur, Charizard and Blastoise card artwork.\"><img src=\"assets/archive-refresh-20261104/santa-cruz-details.webp\" alt=\"Official Santa Cruz decks featuring Venusaur, Charizard and Blastoise card artwork.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Official collaboration picture © The Pokémon Company/Santa Cruz. Card artwork is carried onto the larger board format. <a href=\"https://www.pokemon.com/us/news/pokemon-tcg-santa-cruz-skateboard-decks-available-now\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure>"}, {"heading": "The announced collection", "html": "<figure class=\"feature-reference\"><a href=\"assets/archive-refresh-20261104/santa-cruz-boards.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Official blind-bag Santa Cruz skateboard packaging and illustrated design lineup.\"><img src=\"assets/archive-refresh-20261104/santa-cruz-boards.webp\" alt=\"Official blind-bag Santa Cruz skateboard packaging and illustrated design lineup.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Official blind-bag packaging/design reference © The Pokémon Company/Santa Cruz. <a href=\"https://www.pokemon.com/us/news/pokemon-tcg-santa-cruz-skateboard-decks-available-now\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><p>The source described 30 designs and three gold glitter variants, each using a collage of ten cards. Its examples included Base Set Charizard by Mitsuhiro Arita, Plasma Storm Lugia-EX by Toyste Beach and Evolving Skies Umbreon VMAX by KEIICHIRO ITO.</p><p>The announced variant decks included a design booklet and collectible sticker. The source named Pokémon Center, Santa Cruz and local skate shops as release channels. This retrospective does not confirm present stock, distribution odds or secondary prices.</p>"}, {"heading": "Try an art-first collecting question", "html": "<figure class=\"feature-reference\"><a href=\"assets/modern-006-high.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\"><img src=\"assets/modern-006-high.webp\" alt=\"English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>English Umbreon VMAX · Evolving Skies · 215/203. Catalogue artwork via TCGdex; © Pokémon/Nintendo/Creatures/GAME FREAK. A reference scan does not establish a seller copy’s condition. <a href=\"https://api.tcgdex.net/v2/en/sets/swsh7\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><p>Pick a favourite illustration and name its artist. Look at the character’s pose, the setting and the colours before checking a price. A larger format can reveal details that are easy to miss in a binder pocket.</p><p>A board and a trading card still need their own identities. Shared art does not make the merchandise a card-index constituent or make their prices directly comparable.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>The connection is the illustration, and that is enough to enjoy the story.</strong> Compare the artwork, credit the artist and keep any later buying or price research separate from the appeal of the design.</p></div>"}], "sources": [{"label": "Pokémon — TCG & Santa Cruz skateboard announcement · 17 October 2026", "url": "https://www.pokemon.com/us/news/pokemon-tcg-santa-cruz-skateboard-decks-available-now", "publishedAt": "2026-10-17", "checkedAt": "2026-11-02", "type": "Original collaboration announcement"}], "related": ["welcome", "japanese-card-research"], "cta": {"label": "Browse the Card Desk journal", "href": "#journal"}, "bodyWordCount": 291, "reportedWordCount": 124, "kind": "News", "publicationStatus": "Published 3 November 2026", "image": "assets/archive-refresh-20261104/santa-cruz-details.webp", "imageAlt": "Official Santa Cruz skateboard decks featuring Venusaur, Charizard and Blastoise card artwork.", "imageCredit": "Official Pokémon × Santa Cruz collaboration picture © The Pokémon Company/Santa Cruz, 17 October 2026.", "publishedAt": "2026-11-03", "status": "published", "visualStyle": "source-media-v1", "author": {"type": "person", "id": "oscar", "name": "Oscar"}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/santa-cruz-details.webp", "imageCaption": "Official Pokémon × Santa Cruz collaboration picture © The Pokémon Company/Santa Cruz, 17 October 2026.", "retrospective": true}, {"slug": "pocket-october-producer-letter", "title": "Pocket’s proposed six-week rhythm puts collecting pace in focus", "eyebrow": "Archive · Digital collecting", "summary": "The October producer letter proposed a slower pack cycle and more activities between releases. A picture-led guide to the plan and its collecting consequences.", "minutes": 4, "art": "archive", "date": "2026-11-02", "eventDate": "2026-10-15", "sourcePublishedAt": "2026-10-15", "preparedAt": "2026-11-02", "dateNote": "Reports the 15 October producer letter as an announcement. Individual feature availability was not rechecked in the game.", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>More breathing room was the plan.</h3><p>The October letter proposed roughly six weeks between new booster releases, with more activities between them. The actual rewards and requirements still determine how collecting feels.</p></aside>"}, {"heading": "Read the change as a dated plan", "html": "<figure class=\"feature-reference\"><a href=\"assets/archive-refresh-20261104/pocket-letter.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Pokémon Trading Card Game Pocket logo from the official October producer letter.\"><img src=\"assets/archive-refresh-20261104/pocket-letter.webp\" alt=\"Pokémon Trading Card Game Pocket logo from the official October producer letter.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>Official producer-letter artwork © The Pokémon Company, 15 October 2026. <a href=\"https://www.pokemon.com/us/news/read-the-pokemon-tcg-pocket-october-2026-producer-letter\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><figure class=\"queue-explainer\"><h3>The proposed release rhythm</h3><div class=\"cadence-pair\"><div><strong>≈4</strong><span>weeks between packs before the change</span></div><b aria-hidden=\"true\">→</b><div><strong>≈6</strong><span>weeks in the planned new series</span></div></div><figcaption>Approximate cycles described in the 15 October producer letter. This diagram is a plan summary, not confirmation that every feature shipped.</figcaption></figure>"}, {"heading": "What was proposed", "html": "<p>The Operations Team’s 15 October letter discussed a new series planned for late October. Alongside the longer cycle, it described dual-type Pokémon, collection-mission immersive rewards and a First Partners special pack with weekly stamina recovery.</p><p>It also proposed Community Decks, easier unlimited-use rental decks and improvements for finding trading partners’ missing cards and wishlists. Development details and timing were subject to change; this article reports the letter rather than independently confirming every feature’s rollout.</p>"}, {"heading": "Use the space between packs", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Choose one goal</strong><p>A favourite illustration, a collection page or a playable deck is a clearer goal than everything at once.</p></div><div><b>2</b><strong>Check the requirements</strong><p>Look at the actual missions, rewards and available cards before deciding whether completion is practical.</p></div><div><b>3</b><strong>Separate digital from physical</strong><p>A Pocket change does not establish a paper-card print run or a graded-card price.</p></div></div><p>The appeal of a collection is often the small, visible goal: finish a favourite Pokémon’s page, find one particular illustration, or build a deck that actually works. A release calendar can support those goals, but a longer interval alone does not tell us how easy completion will become. The rewards, requirements and actual experience still matter.</p><p>For a family collection, a simple wishlist can be more useful than another ranking. Separate the cards you like looking at from the ones needed for play, then choose one achievable goal for the next session. That leaves room to enjoy a new card without treating every unfinished set as a problem.</p><p>Our desk will keep digital collecting stories distinct from paper-card market research. A popular Pocket illustration can be a good conversation starter; it is not automatically a price signal for a physical card with similar art. That connection needs its own evidence before it belongs in the TCG Modern Index discussion.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>A longer proposed cycle can give a collection more room.</strong> Judge the actual missions and collecting experience as they arrive. Keep the October plan, later implementation and physical-card market claims as separate facts.</p></div>"}], "sources": [{"label": "Pokémon — October 2026 TCG Pocket producer letter · 15 October 2026", "url": "https://www.pokemon.com/us/news/read-the-pokemon-tcg-pocket-october-2026-producer-letter", "publishedAt": "2026-10-15", "checkedAt": "2026-11-02", "type": "Original developer letter"}], "related": ["welcome", "how-the-index-works"], "cta": {"label": "Explore more from the Card Desk", "href": "#journal"}, "bodyWordCount": 298, "reportedWordCount": 139, "kind": "News", "publicationStatus": "Published 3 November 2026", "image": "assets/archive-refresh-20261104/cover-pocket.webp", "imageAlt": "A conceptual phone with the Pokémon TCG Pocket logo and a labelled planned four-to-six-week cycle.", "imageCredit": "BuyTrigger.Cards explanatory graphic using the official Pocket logo © The Pokémon Company. Concept layout, not a game screenshot.", "publishedAt": "2026-11-03", "status": "published", "visualStyle": "brand-graphic-v1", "author": {"type": "person", "id": "oscar", "name": "Oscar"}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-pocket.webp", "imageCaption": "BuyTrigger.Cards explanatory graphic using the official Pocket logo © The Pokémon Company. Concept layout, not a game screenshot.", "retrospective": true}, {"slug": "welcome", "title": "A father, a son, and a better way to follow cards.", "eyebrow": "MEET ALEX & OSCAR", "summary": "A father-and-son view of card artwork, collecting news and the numbers behind a decision. Meet Alex and Oscar, then choose where to start.", "minutes": 4, "art": "family", "date": "2 November 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Enjoy the pictures. Ask questions of the numbers.</h3><p>BuyTrigger.Cards is Alex and Oscar’s father-and-son collecting publication: artwork, news, releases and practical explanations in one place.</p></aside>"}, {"heading": "The people behind the badge", "html": "<figure class=\"feature-reference\"><a href=\"assets/logo-gengar-vaporeon-v1.png\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: The approved BuyTrigger.Cards father-and-son badge with Gengar and Vaporeon cards.\"><img src=\"assets/logo-gengar-vaporeon-v1.png\" alt=\"The approved BuyTrigger.Cards father-and-son badge with Gengar and Vaporeon cards.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>The BuyTrigger.Cards family badge.</figcaption></figure><p>Pokémon is at the centre of this project, with room for other cards and the anime we enjoy. The cartoon collectors are our brand characters. Their presence is not a claim that a pictured scene or outing happened.</p><p>The point is to make the hobby easier to follow: see the artwork clearly, find the original announcement and understand what sits behind a quoted price.</p>"}, {"heading": "Start with the cards", "html": "<figure class=\"feature-reference\"><a href=\"assets/archive-refresh-20261104/modern-interface.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Public TCG Modern Index interface with actual catalogue artwork and dated Raw guide history.\"><img src=\"assets/archive-refresh-20261104/modern-interface.webp\" alt=\"Public TCG Modern Index interface with actual catalogue artwork and dated Raw guide history.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>BuyTrigger.Cards public-interface screenshot, 4 November 2026. Catalogue art credits and dated price sources remain on the index. <a href=\"https://buytrigger.cards/tcg-modern-index.html\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><div class=\"archive-steps\"><div><b>1</b><strong>Look closer</strong><p>Open a card for its catalogue picture, exact issue and dated history.</p></div><div><b>2</b><strong>Catch up</strong><p>Use Newsroom for the short update, Features for context and Drops for source-linked release dates.</p></div><div><b>3</b><strong>Try the numbers</strong><p>Use the calculator to see what purchase, grading and selling costs leave behind.</p></div></div>"}, {"heading": "Know what a number represents", "html": "<p>Raw, PSA 9 and PSA 10 are different outcomes, not three amounts to add together. A market guide is different from a verified individual sale. Missing history remains a gap and an older observation keeps its original date.</p><p>The public publication is free to read. The My collection link leads to a separate private owner tracker; it is not a public account-signup route. Advertising and affiliate links keep their own labels.</p>"}, {"heading": "A useful first visit", "html": "<div class=\"closing-call\"><p><strong>Open one card, read one story and follow one original source.</strong> You should leave with a clearer picture of what you like and what the available evidence can actually tell you.</p></div>"}], "sources": [{"label": "BuyTrigger.Cards · public TCG Modern Index", "url": "https://buytrigger.cards/tcg-modern-index.html"}, {"label": "BuyTrigger.Cards · sources and methods", "url": "https://buytrigger.cards/#method"}], "related": ["how-the-index-works", "psa10-is-not-profit"], "cta": {"label": "Explore TCG Modern Index", "href": "tcg-modern-index.html"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "publishedAt": "2026-11-03", "status": "published", "image": "assets/family.png", "visualStyle": "family-anime-v1", "imageAlt": "Alex and Oscar, the established dark-haired Asian father-and-son collecting mascots", "imageCredit": "Original BuyTrigger.Cards family illustration.", "author": {"type": "family", "id": "alex-and-oscar", "name": "Alex & Oscar", "members": ["alex-koh", "oscar"]}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1"}, {"slug": "psa10-is-not-profit", "title": "A PSA 10 price is not your profit.", "eyebrow": "THE NUMBERS, EXPLAINED", "summary": "The $100 headline becomes $16.01 in our hypothetical example. See how the costs and a lower grade change what remains.", "minutes": 4, "art": "cards", "date": "2 November 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>The sale price is the beginning of the calculation.</h3><p>A $100 PSA 10 exit leaves $16.01 in our labelled example. A different grade, selling fee or route cost changes the result.</p></aside>"}, {"heading": "Start with the money committed", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\"><img src=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" alt=\"Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>PSA announcement photograph © PSA/Collectors, 28 October 2026. The pictured cards are source examples; calculations in our guides are hypothetical. <a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><div class=\"archive-steps\"><div><b>1</b><strong>Delivered entry</strong><p>What the actual card costs to arrive.</p></div><div><b>2</b><strong>Grading journey</strong><p>Service fee, shipping, insurance, handling and applicable taxes.</p></div><div><b>3</b><strong>Selling costs</strong><p>Marketplace/payment charges and any cost needed to complete the exit.</p></div></div>"}, {"heading": "Three outcomes, counted separately", "html": "<figure class=\"feature-chart\"><h3>The $100 exit leaves $16.01 in this example</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/archive-refresh-20261104/net-outcomes-mobile.png\"><img src=\"assets/archive-refresh-20261104/net-outcomes.png\" alt=\"Hypothetical net outcomes: Raw minus 3.70 dollars, PSA 9 minus 26.49 dollars, PSA 10 plus 16.01 dollars.\"></picture><figcaption>Illustrative US-dollar model, not market quotes: $19 entry, $39.99 grading, $10 other grading costs and 15% selling charge. Raw avoids the grading-related costs.</figcaption><details><summary>View assumptions and data</summary><div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Outcome</th><th>Gross sale</th><th>Net</th><th>Net after 10% sale fall</th></tr></thead><tbody><tr><td>Raw</td><td>$18.00</td><td>$-3.70</td><td>$-5.23</td></tr><tr><td>PSA 9</td><td>$50.00</td><td>$-26.49</td><td>$-30.74</td></tr><tr><td>PSA 10</td><td>$100.00</td><td>$16.01</td><td>$7.51</td></tr></tbody></table></div><p><a href=\"assets/archive-refresh-20261104/net-outcomes.csv\" download>Download CSV</a></p></details></figure><p>Raw, PSA 9 and PSA 10 are alternatives for one card. The raw route avoids the grading bill; the graded routes carry it even when the result disappoints. Keep one currency and the exchange-rate date with the calculation.</p><p>The chart uses $19 entry, $39.99 grading, $10 other grading-related costs and a 15% selling charge. These are teaching inputs, not a live quote for the pictured cards.</p>"}, {"heading": "Then lower the exit", "html": "<p>With a 10% lower sale and the same costs, the hypothetical PSA 10 profit falls to $7.51 and PSA 9 falls to a $30.74 loss. Graded capital committed in this model is $68.99. The attractive-looking gross sale is much larger than the money left over.</p><p>A photograph can start a condition review. It cannot promise the eventual grade, and a seller’s description is not PSA’s own standard. Missing front/back or surface evidence remains a reason to ask for more information.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>Compare the net result at more than one grade before treating a price gap as an opportunity.</strong> Change the example’s inputs in the calculator. An attractive PSA 10 price alone does not establish a profitable purchase.</p></div>"}], "sources": [{"label": "PSA: official grading standards", "url": "https://www.psacard.com/gradingstandards"}], "related": ["under20-upside", "psa-value-returns"], "cta": {"label": "Change the costs and see all three outcomes", "href": "#calculator"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "publishedAt": "2026-11-03", "status": "published", "image": "assets/archive-refresh-20261104/cover-profit.webp", "visualStyle": "brand-graphic-v1", "imageAlt": "Charizard catalogue artwork beside the words Price is not profit and the cost categories.", "imageCredit": "BuyTrigger.Cards editorial graphic; catalogue artwork via TCGdex. All numerical examples in this guide are hypothetical, not prices for the pictured card.", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-profit.webp", "imageCaption": "BuyTrigger.Cards editorial graphic; catalogue artwork via TCGdex. All numerical examples in this guide are hypothetical, not prices for the pictured card."}, {"slug": "under20-upside", "title": "Under $20. A $100 PSA 10. Is there actually a deal?", "eyebrow": "TARGETS LAB", "summary": "A cheap Raw price and a much higher PSA 10 reference can hide a loss at PSA 9. Four visual checks and the complete hypothetical cost model.", "minutes": 4, "art": "cards", "date": "2 November 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>A five-times price gap can still leave a weak result.</h3><p>The $19-to-$100 example is a research prompt, not a passing purchase. Look at the available copy, actual exits, lower-grade downside and full cost.</p></aside>"}, {"heading": "Four gates before a shortlist", "html": "<figure class=\"feature-reference\"><a href=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\"><img src=\"assets/features-20261104-visual-v3/psa-value-announcement.webp\" alt=\"Three encapsulated trading cards in PSA’s official Value-service announcement photograph.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>PSA announcement photograph © PSA/Collectors, 28 October 2026. The pictured cards are source examples; calculations in our guides are hypothetical. <a href=\"https://www.psacard.com/articles/articleview/15779/psa-reopens-value-service-level\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure><div class=\"archive-steps\"><div><b>1</b><strong>Available entry</strong><p>Use a real available copy and its delivered cost.</p></div><div><b>2</b><strong>Exact exit evidence</strong><p>Match issue, language, variant, grader and grade; separate completed sales from asks and guides.</p></div><div><b>3</b><strong>PSA 9 downside</strong><p>Calculate what remains after all grading and selling costs if the result is one grade lower.</p></div><div><b>4</b><strong>Copy quality</strong><p>Review original fronts, backs, edges, corners and surface. Missing views are missing evidence.</p></div></div>"}, {"heading": "Why the example fails", "html": "<figure class=\"feature-chart\"><h3>The $100 exit leaves $16.01 in this example</h3><picture><source media=\"(max-width:650px)\" srcset=\"assets/archive-refresh-20261104/net-outcomes-mobile.png\"><img src=\"assets/archive-refresh-20261104/net-outcomes.png\" alt=\"Hypothetical net outcomes: Raw minus 3.70 dollars, PSA 9 minus 26.49 dollars, PSA 10 plus 16.01 dollars.\"></picture><figcaption>Illustrative US-dollar model, not market quotes: $19 entry, $39.99 grading, $10 other grading costs and 15% selling charge. Raw avoids the grading-related costs.</figcaption><details><summary>View assumptions and data</summary><div class=\"table-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"Comparison table\"><table class=\"archive-table\"><thead><tr><th>Outcome</th><th>Gross sale</th><th>Net</th><th>Net after 10% sale fall</th></tr></thead><tbody><tr><td>Raw</td><td>$18.00</td><td>$-3.70</td><td>$-5.23</td></tr><tr><td>PSA 9</td><td>$50.00</td><td>$-26.49</td><td>$-30.74</td></tr><tr><td>PSA 10</td><td>$100.00</td><td>$16.01</td><td>$7.51</td></tr></tbody></table></div><p><a href=\"assets/archive-refresh-20261104/net-outcomes.csv\" download>Download CSV</a></p></details></figure>"}, {"heading": "A gross multiple hides the capital", "html": "<p>The hypothetical PSA 10 sale is about 5.3 times the $19 entry, but that comparison omits grading, related costs and selling charges. The model commits $68.99 before the graded exit. A $16.01 profit is roughly 23% of that capital; the $7.51 stressed result is roughly 11%.</p><p>The hypothetical PSA 9 case loses money. That combination fails a demanding downside-and-return screen even though the raw-to-PSA 10 headline looks dramatic. These percentages describe only the stated example; they are not a forecast for a real card.</p>"}, {"heading": "Let the evidence decide the length", "html": "<p>A shortlist should explain why each exact available copy passes, what could invalidate it and when the evidence was checked. A front photograph, a favourite character or a cheap asking price cannot supply missing sales or condition evidence.</p><p>If no copy meets the rules, an empty passing shortlist is a useful result. Research leads can stay labelled as leads without being presented as cleared purchases.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>Keep the gross gap as a discovery filter, then require the net and downside case to work.</strong> The example does not pass. Recalculate it yourself before applying the same method to an actual available copy.</p></div>"}], "sources": [{"label": "PSA: official grading standards", "url": "https://www.psacard.com/gradingstandards"}], "related": ["psa10-is-not-profit", "japanese-card-research"], "cta": {"label": "Test the $19 example yourself", "href": "#calculator"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "publishedAt": "2026-11-03", "status": "published", "image": "assets/archive-refresh-20261104/cover-under20.webp", "visualStyle": "brand-graphic-v1", "imageAlt": "An illustrated card inspection beside the words Look closer. Four checks before grading.", "imageCredit": "BuyTrigger.Cards explanatory graphic using the approved card-inspection illustration. The guide’s prices are hypothetical.", "author": {"type": "person", "id": "alex-koh", "name": "Alex Koh", "bio": "Collector and creator of BuyTrigger.Cards."}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-under20.webp", "imageCaption": "BuyTrigger.Cards explanatory graphic using the approved card-inspection illustration. The guide’s prices are hypothetical."}, {"slug": "how-the-index-works", "title": "How to read the TCG Modern Index.", "eyebrow": "INSIDE THE INDEX", "summary": "Read the real interface, open the card artwork and follow a dated observation. A visual guide to points, prices, gaps and the source behind them.", "minutes": 4, "art": "cards", "date": "3 November 2026", "sections": [{"heading": "The quick take", "html": "<aside class=\"quick-verdict\"><span class=\"kicker\">THE QUICK TAKE</span><h3>Follow the cards, the dates and the source.</h3><p>Index points show a basket’s movement on a shared scale. They are not a card’s dollar price or a return after fees.</p></aside>"}, {"heading": "Read the real screen", "html": "<figure class=\"feature-reference\"><a href=\"assets/archive-refresh-20261104/modern-performance.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: Public TCG Modern Index Raw performance view and its reported date range.\"><img src=\"assets/archive-refresh-20261104/modern-performance.webp\" alt=\"Public TCG Modern Index Raw performance view and its reported date range.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>BuyTrigger.Cards screenshot, 4 November 2026. These are dated provider Raw guides; history is not an after-fee return. <a href=\"https://buytrigger.cards/tcg-modern-index.html\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure>"}, {"heading": "Choose the question first", "html": "<div class=\"archive-steps\"><div><b>1</b><strong>Index points</strong><p>A shared starting scale for movement.</p></div><div><b>2</b><strong>Card price</strong><p>The individual issue’s own dated guide and currency.</p></div><div><b>3</b><strong>History window</strong><p>The actual observed range and eligible basket, shown beside the chart.</p></div></div><p>The Modern Index’s 2026 trend uses the cards with history from January. Latest lineup uses a more recent shared window. Read the displayed constituent count and dates; neither view promises a full year of observations for every current card.</p><p>BlueChip follows its separate high-value lineup. Its longer-history view covers the eligible subset shown on that screen. Earlier prices belong to a selection assembled later, so the chart is retrospective rather than evidence of a basket chosen back then.</p>"}, {"heading": "Open the actual card", "html": "<figure class=\"feature-reference\"><a href=\"assets/modern-006-high.webp\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open larger picture: English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\"><img src=\"assets/modern-006-high.webp\" alt=\"English Umbreon VMAX, Evolving Skies 215/203, shown as a catalogue reference.\" loading=\"lazy\" decoding=\"async\"></a><figcaption>English Umbreon VMAX · Evolving Skies · 215/203. Catalogue artwork via TCGdex; © Pokémon/Nintendo/Creatures/GAME FREAK. A reference scan does not establish a seller copy’s condition. <a href=\"https://api.tcgdex.net/v2/en/sets/swsh7\" target=\"_blank\" rel=\"noopener noreferrer\">Original source ↗</a></figcaption></figure>"}, {"heading": "Read the evidence behind the line", "html": "<p>Public Raw prices are combined-condition provider market guides, not independently verified individual completed sales. A missing observation stays missing. Retained older observations keep their date. Read each card’s edition and language notes before comparing it with a seller’s copy.</p><p>The current public edition keeps PSA 9/10 values pending; pending is unknown, not zero. All three grades are alternatives and must not be added together. TCGCSV documents its archive from 8 February 2024, which limits claims about that source’s earlier history.</p><p>A catalogue scan is useful for identification and appreciating art. It cannot prove the condition or value of a specific physical copy offered for sale.</p>"}, {"heading": "The verdict", "html": "<div class=\"closing-call\"><p><strong>Use the chart to start a question, then inspect the card and its evidence.</strong> Read the source date, basket and gaps before drawing a conclusion. The index is a research view, not a prediction, fund or guaranteed result.</p></div>"}], "sources": [{"label": "TCGCSV: price-guide source and archive information", "url": "https://tcgcsv.com/faq"}, {"label": "BuyTrigger.Cards: price notes and sources", "url": "https://buytrigger.cards/tcg-modern-index.html#sources"}], "related": ["welcome", "psa10-is-not-profit"], "cta": {"label": "Explore TCG Modern Index research", "href": "tcg-modern-index.html"}, "preparedAt": "2026-11-02", "publicationStatus": "Published 3 November 2026", "publishedAt": "2026-11-03", "status": "published", "modifiedAt": "2026-11-03", "image": "assets/archive-refresh-20261104/cover-index.webp", "visualStyle": "brand-graphic-v1", "imageAlt": "Umbreon VMAX catalogue artwork beside the words Follow the cards. Date, price and source.", "imageCredit": "BuyTrigger.Cards editorial graphic using Umbreon VMAX catalogue artwork via TCGdex. Source credits remain in the index.", "author": {"type": "family", "id": "alex-and-oscar", "name": "Alex & Oscar", "members": ["alex-koh", "oscar"]}, "updatedAt": "2026-11-04", "editorialFormat": "visual-quick-read-v1", "thumbnail": "assets/archive-refresh-20261104/cover-index.webp", "imageCaption": "BuyTrigger.Cards editorial graphic using Umbreon VMAX catalogue artwork via TCGdex. Source credits remain in the index."}], "wire": [{"id": "cardlabo-mito-hadou-seeker-lottery-2026-11-04", "eventKey": "c-labo-mito-hadou-seeker-lottery-2026-11-04", "date": "2026-11-04", "displayDate": "4 Nov · Mito, Japan", "category": "Japan", "kind": "Retailer lottery notice", "title": "CardLabo Mito’s Hadou Seeker lottery winners need two store visits.", "summary": "CardLabo Mito’s Hadou Seeker lottery runs 4–6 November via X. Winners are notified on 7–8 November and must visit the store twice: reserve during 9–15 November, then collect during 27 November–4 December. Reservation requires ID and a ¥1,000 cash deposit, which is not refunded if collection is missed. Packs come without the box or shrink-wrap. Dates are local to Japan; check the branch’s full rules before entering.", "sourceLabel": "CardLabo Mito", "url": "https://www.c-labo.jp/shop/mito/blog/623734/", "checkedAt": "2026-11-04T13:37:23Z", "sourcePublishedAt": "2026-11-04", "ctaUrl": "drops.html", "ctaLabel": "Check regional release dates →", "visual": "japan", "author": {"id": "hana-mori", "name": "Hana Mori", "type": "named_ai_correspondent", "label": "AI correspondent", "beat": "Japan desk"}, "newsRevision": 1}, {"id": "psa-toronto-november-2026", "eventKey": "psa-toronto-expo-2026-11-05", "date": "2026-11-03", "displayDate": "3 Nov · Canada", "category": "Grading", "kind": "Official notice", "title": "Taking cards to Toronto? Check the grading route first.", "summary": "PSA’s 3 November notice covers on-site grading at the Toronto Sport Card Expo, 5–8 November. TCG cards are eligible, with a 20-card limit per customer and service availability restrictions. Orders must be created through the Canadian submission centre.", "sourceLabel": "PSA", "url": "https://www.psacard.com/articles/articleview/15774/on-site-grading-and-specials-at-the-toronto-sport-card-expo", "checkedAt": "2026-11-03T23:35:00Z", "sourcePublishedAt": "2026-11-03", "ctaUrl": "#calculator", "ctaLabel": "Work out grading costs →", "visual": "grading"}, {"id": "japan-card-stores-november-2026", "eventKey": "pokemon-jp-five-stores-2026-11-13", "date": "2026-10-30", "displayDate": "Updated 30 Oct · Japan", "category": "Japan", "kind": "Official update", "title": "Five temporary Pokémon Card Stores open in Japan this November.", "summary": "The official schedule lists five venues opening on 13 November, including Aichi Togo, Shizuoka and Fujimi. Closing dates vary by venue. If a visit is part of your trip, check the location’s opening window and entry rules before travelling.", "sourceLabel": "Pokémon Card Game Japan", "url": "https://www.pokemon-card.com/info/004753.html", "checkedAt": "2026-11-03T23:35:00Z", "sourcePublishedAt": "2024-12-27", "sourceUpdatedAt": "2026-10-30", "related": "japanese-card-research", "ctaLabel": "Explore our Japan research →", "visual": "japan"}, {"id": "hadou-seeker-japan-release-2026", "eventKey": "pokemon-jp-m7-2026-11-27", "date": "2026-10-23", "displayDate": "23 Oct · Japan", "category": "Releases", "kind": "Official announcement", "title": "Japan’s next MEGA expansion is dated for 27 November.", "summary": "The official ハドウシーカー product page lists a 27 November Japanese release, with five cards per pack and a ¥200 suggested retail price including tax. The reveals include Mega Lucario Z ex, Mega Garchomp Z ex and Mega Absol Z ex. These are Japanese product details.", "sourceLabel": "Pokémon Card Game Japan", "url": "https://www.pokemon-card.com/ex/m7/", "checkedAt": "2026-11-03T23:35:00Z", "sourcePublishedAt": "2026-10-23", "ctaUrl": "#journal", "ctaLabel": "More collecting stories →", "visual": "release", "visualMark": "27 NOV"}, {"id": "fanatics-november-premier-preview-2026", "eventKey": "fanatics-premier-preview-2026-11", "date": "2026-11-03", "displayDate": "Checked 3 Nov · Auction preview", "category": "Auctions", "kind": "Auction-house preview", "title": "Fanatics points to 1990s Pokémon in its November Premier preview.", "summary": "Fanatics Collect’s homepage preview includes Pokémon from the 1990s in the upcoming November Premier auction. This is a catalogue lead, not a completed-sale result. Exact printing, grade and the final transaction will determine what any future price tells us.", "sourceLabel": "Fanatics Collect", "url": "https://www.fanaticscollect.com/", "checkedAt": "2026-11-03T23:35:00Z", "sourcePublishedAt": null, "visual": "auction"}], "archiveCoverage": {"sourceWindowStart": "2026-10-13", "sourceWindowEnd": "2026-11-02", "preparedAt": "2026-11-02", "completeDailyArchive": false, "description": "Curated three-week catch-up plus evergreen guides"}, "publishedAt": "2026-11-03", "featuredArticle": "delta-reign-friday-uk-upc-release-check", "wireEdition": {"id": "002", "publishedAt": "2026-11-03", "checkedAt": "2026-11-03T23:35:00Z", "label": "3 November briefing", "automatic": false}};
